-- Generated by rice-render for {{ meta.title }}: lualine theme "rice".
-- The mode is a pill coloured by gradient stop; the rest stays quiet.
local c = {
  bg      = "{{ roles.surface }}",
  fg      = "{{ roles.fg }}",
  muted   = "{{ roles.muted }}",
  grad    = { {{ gradient.stops | closed | quote | join(", ") }} },
}
local function stop(i) return c.grad[((i - 1) % #c.grad) + 1] end
local function mode(i)
  return {
    a = { fg = c.fg, bg = stop(i), gui = "bold" },
    b = { fg = c.fg, bg = c.bg },
    c = { fg = c.muted, bg = c.bg },
  }
end
return {
  normal   = mode(5),
  insert   = mode(2),
  visual   = mode(1),
  replace  = mode(4),
  command  = mode(3),
  terminal = mode(2),
  inactive = { a = { fg = c.muted, bg = c.bg }, b = { fg = c.muted, bg = c.bg }, c = { fg = c.muted, bg = c.bg } },
}
